1	package retention
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"path/filepath"
10		"sync"
11		"syscall"
12	)
13	
14	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
15	const (
16		stateFileName = "retention-state.json"
17		lockFileName  = ".retention.lock"
18	)
19	
20	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
21	//
22	// 同一个目录可以被本机上的多个程序（进程）同时打开：
23	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
24	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
25	type Store struct {
26		dir string
27	
28		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
29		opMu sync.RWMutex
30	}
31	
32	// Open 打开（或创建）一个本地保存位置。
33	// 目录不存在时会创建；状态文件损坏时返回错误，已有记录不会被覆盖。
34	func Open(dir string) (*Store, error) {
35		if dir == "" {
36			return nil, errors.New("retention: 保存位置不能为空")
37		}
38		if err := os.MkdirAll(dir, 0o755); err != nil {
39			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
40		}
41		s := &Store{dir: dir}
42		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
43		if _, err := s.load(); err != nil {
44			return nil, err
45		}
46		return s, nil
47	}
48	
49	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
50	func (s *Store) Close() error { return nil }
51	
52	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
53	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
54	
55	// lock 取得跨进程排他锁，返回解锁函数。
56	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
57	func (s *Store) lock() (func(), error) {
58		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
59		if err != nil {
60			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
61		}
62		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
63			f.Close()
64			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
65		}
66		return func() {
67			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
68			_ = f.Close()
69		}, nil
70	}
71	
72	// rlock 取得跨进程共享锁，用于只读核对。
73	func (s *Store) rlock() (func(), error) {
74		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
75		if err != nil {
76			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
77		}
78		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
79			f.Close()
80			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
81		}
82		return func() {
83			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
84			_ = f.Close()
85		}, nil
86	}
87	
88	// load 从磁盘读取最新状态。文件不存在时返回一份空状态。
89	func (s *Store) load() (*storeData, error) {
90		data := newStoreData()
91		f, err := os.Open(s.statePath())
92		if err != nil {
93			if errors.Is(err, os.ErrNotExist) {
94				return data, nil
95			}
96			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
97		}
98		defer f.Close()
99		if err := json.NewDecoder(f).Decode(data); err != nil {
100			if errors.Is(err, io.EOF) {
101				// 空文件视为空状态。
102				return newStoreData(), nil
103			}
104			return nil, fmt.Errorf("retention: 状态文件已损坏: %w", err)
105		}
106		if data.Archives == nil {
107			data.Archives = map[string]*archiveRecord{}
108		}
109		if data.Manifests == nil {
110			data.Manifests = map[string]*manifestRecord{}
111		}
112		// 兼容引入修订功能之前保存的保管库：没有记录最初截止日时，
113		// 登记截止日就是最初截止日。
114		for _, ar := range data.Archives {
115			if ar.InitialEnd.IsZero() {
116				ar.InitialEnd = ar.End
117			}
118		}
119		return data, nil
120	}
121	
122	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
123	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
124	func (s *Store) save(data *storeData) error {
125		buf, err := json.MarshalIndent(data, "", "  ")
126		if err != nil {
127			return fmt.Errorf("retention: 状态编码失败: %w", err)
128		}
129		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
130		if err != nil {
131			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
132		}
133		tmpName := tmp.Name()
134		cleanup := func() { _ = os.Remove(tmpName) }
135		if _, err := tmp.Write(buf); err != nil {
136			tmp.Close()
137			cleanup()
138			return fmt.Errorf("retention: 写入状态失败: %w", err)
139		}
140		if err := tmp.Sync(); err != nil {
141			tmp.Close()
142			cleanup()
143			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
144		}
145		if err := tmp.Close(); err != nil {
146			cleanup()
147			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
148		}
149		if err := os.Rename(tmpName, s.statePath()); err != nil {
150			cleanup()
151			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
152		}
153		// 刷目录，确保 rename 在崩溃后仍然落盘。
154		if dir, err := os.Open(s.dir); err == nil {
155			_ = dir.Sync()
156			_ = dir.Close()
157		}
158		return nil
159	}
160	
161	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
162	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
163	func (s *Store) mutate(fn func(*storeData) error) error {
164		s.opMu.Lock()
165		defer s.opMu.Unlock()
166		unlock, err := s.lock()
167		if err != nil {
168			return err
169		}
170		defer unlock()
171		data, err := s.load()
172		if err != nil {
173			return err
174		}
175		if err := fn(data); err != nil {
176			return err
177		}
178		return s.save(data)
179	}
180	
181	// view 在共享锁内重读状态并执行只读查询。
182	func (s *Store) view(fn func(*storeData) error) error {
183		s.opMu.RLock()
184		defer s.opMu.RUnlock()
185		unlock, err := s.rlock()
186		if err != nil {
187			return err
188		}
189		defer unlock()
190		data, err := s.load()
191		if err != nil {
192			return err
193		}
194		return fn(data)
195	}
